/**
 * Apply import rules to already-parsed rows.
 * `amount` must be integer cents; `today` must be YYYY-MM-DD.
 * Duplicate identity is the exact date, amount, and payee tuple.
 *
 * @returns {{ rows: object[], imported: number, skipped: number, deduplicated: number }}
 */
export function importRows(rows, today) {
	function isValidDate(value) {
		if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
			return false;
		}
		const date = new Date(`${value}T00:00:00Z`);
		return Number.isFinite(date.getTime())
			&& date.toISOString().slice(0, 10) === value;
	}

	if (!Array.isArray(rows)) {
		throw new Error("ledger: import rows must be an array");
	}
	if (!isValidDate(today)) {
		throw new Error("ledger: invalid today date; expected YYYY-MM-DD");
	}

	// Validate before processing so bad input cannot produce partial warnings.
	for (const [index, row] of rows.entries()) {
		if (!row || typeof row !== "object"
			|| !isValidDate(row.date)
			|| typeof row.payee !== "string"
			|| !Number.isSafeInteger(row.amount)
			|| (row.memo != null && typeof row.memo !== "string")) {
			throw new Error(`ledger: invalid import row ${index + 1}`);
		}
	}

	const rowsToImport = [];
	const seen = new Map();
	let skipped = 0;
	let deduplicated = 0;

	for (const [index, row] of rows.entries()) {
		// Future rows are skipped, not counted as duplicates or imported.
		if (row.date > today) {
			console.warn(
				`ledger: skipping future-dated row ${index + 1}: ${row.date}`,
			);
			skipped++;
			continue;
		}

		const key = JSON.stringify([row.date, row.amount, row.payee]);
		if (seen.has(key)) {
			deduplicated++;
			continue;
		}
		seen.set(key, true);

		rowsToImport.push({
			...row,
			memo: row.memo == null || row.memo.trim() === ""
				? row.payee
				: row.memo,
		});
	}

	return {
		rows: rowsToImport,
		imported: rowsToImport.length,
		skipped,
		deduplicated,
	};
}
